contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We take an input amount and drive c.play with that amount.
    // The rule: when calling play with any amount, if it does not revert then
    // either the pot increases by the ticket amount, or the pot becomes zero and the bank's balance increased by at least FEE_AMOUNT.
    function run(uint amount) public payable {
        require(address(this).balance >= amount);

        // record observable before-values
        uint beforePot = c.pot();
        address bankAddr = c.bank();
        uint bankBalBefore = address(bankAddr).balance;

        bool reverted;
        // call that may revert
        try c.play{value: amount}() {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint afterPot = c.pot();
        uint bankBalAfter = address(bankAddr).balance;

        // TICKET_AMOUNT and FEE_AMOUNT are constants in C; we cannot access them directly here.
        // But we can express the rule using the observable behavior: when the call does not revert,
        // either pot increased by exactly amount (meaning pot == before + amount), or pot became zero and bank's balance increased by at least 1 (the fee).
        // We don't assert anything when the call reverted.

        assert(reverted || (
            // If not reverted, then one of two cases holds
            (
                // case A: pot increased by amount
                afterPot == beforePot + amount
            ) || (
                // case B: pot reset to zero and bank gained at least 1 wei (fee)
                (afterPot == 0 && bankBalAfter >= bankBalBefore + 1)
            )
        ));
    }

    // allow receiving Ether when c.payable functions send funds here
    receive() external payable {}
}

